import { sceneMarkup, updateScene, demoOffice, character } from './scene.js';
import { normalizeStats, recordMatch, ACHIEVEMENTS } from './progress.js';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = { grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z', people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3a4 4 0 0 1 0 8', briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3', arrow:'M5 12h14 M13 6l6 6-6 6', clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', check:'M5 12l4 4L19 6', book:'M12 5v16 M12 5C9 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1', coffee:'M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4z M17 9h2a3 3 0 0 1 0 6h-2 M7 2v3 M12 2v3', shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6', inbox:'M3 3h18v17H3z M3 13h5l2 3h4l2-3h5', code:'M8 5l-6 7 6 7 M16 5l6 7-6 7 M14 3l-4 18', calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18', receipt:'M5 2l3 2 4-2 4 2 3-2v20l-3-2-4 2-4-2-3 2z M9 8h6 M9 12h6 M9 16h4', slides:'M3 3h18v14H3z M12 17v5 M7 22l5-5 5 5', route:'M5 3v12a4 4 0 0 0 4 4h10 M15 15l4 4-4 4 M5 3l-3 3 M5 3l3 3', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0', logout:'M9 3H3v18h6 M8 12h14 M17 7l5 5-5 5', bolt:'M13 2L4 14h7l-1 8 10-13h-8z', heart:'M12 21S2 14 2 7a5 5 0 0 1 10-1A5 5 0 0 1 22 7c0 7-10 14-10 14', x:'M6 6l12 12 M18 6L6 18', trophy:'M7 3h10v9a5 5 0 0 1-10 0z M7 5H2v4a5 5 0 0 0 5 5 M17 5h5v4a5 5 0 0 1-5 5 M12 17v5 M7 22h10', copy:'M8 8h13v13H8z M16 8V3H3v13h5' };
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.briefcase}"/></svg>`;
const read = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const save = (key,value) => { try { localStorage.setItem(key,JSON.stringify(value)); } catch { toast('Browser storage is unavailable. Progress will last for this session.'); } };
let state=null, stream=null, token=null, connection='Connecting', offset=0, modal=null, taskAnswer=[], voteTarget=null, muted=new Set(read('op-muted',[]));
let drawer=null, chatOpen=false, mapOverview=false, selectedStation=null;
let stats=normalizeStats(read('op-stats',{})), saved=read('op-session',null);
try { token=sessionStorage.getItem('op-token'); } catch {}
const explanations=['I was fixing the shared file.','I was in a meeting.','That clue was planted.'];
function toast(text) { $('#toast').textContent=text; $('#toast').classList.add('show'); clearTimeout(toast.timeout); toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4500); }
async function api(path,data) { const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})},body:JSON.stringify(data)}); const body=await res.json(); if(!res.ok) throw Error(body.error || 'Something went wrong.'); return body; }
function receiveState(next){
 if(state?.code===next.code && (next.revision||0)<(state.revision||0))return;
 if(next.round!==state?.round)voteTarget=null;
 if(next.phase!==state?.phase){if(['incident','meeting','vote','appeal','resolution','ended'].includes(next.phase))drawer='phase';else if(drawer==='phase')drawer=null;selectedStation=null;}
 state=next;offset=next.now-Date.now();connection='Live';
 if(state.phase==='ended'){stats=recordMatch(read('op-stats',stats),state);save('op-stats',stats);}
 render();if(['task','job'].includes(modal?.type)&&state.phase!=='work')closeModal();
}
async function act(type,data={}){const requestToken=token;try{const next=await api('action',{type,data});if(requestToken===token&&next.me)receiveState(next);return true;}catch(error){toast(error.message);return false;}}
function connect(t){
 token=t;try{sessionStorage.setItem('op-token',t);}catch{}stream?.close();
 let closed=false,timer;stream={close(){closed=true;clearTimeout(timer);}};
 async function poll(){
  try{const next=await api('sync',{});if(!closed&&token===t)receiveState(next);}
  catch(error){if(!closed){connection='Reconnecting';if(error.message==='Your session expired. Please join a room.'){closed=true;state=null;token=null;saved=null;drawer=null;chatOpen=false;save('op-session',null);try{sessionStorage.removeItem('op-token');}catch{}render();toast(error.message);}else{if(state)render();else toast(error.message);}}}
  finally{if(!closed)timer=setTimeout(poll,document.hidden?5000:1200);}
 }
 poll();
}
function avatar(p,i=0) { return `<span class="avatar color-${i%6}">${esc(p.name.slice(0,2).toUpperCase())}<i class="presence ${p.connected?'online':''}"></i></span>`; }
function shell(content){return `<div class="game-shell ${state?'in-session':'at-title'}">${content}</div>`;}
function landing(){return `<section class="title-screen"><div class="title-world" aria-hidden="true">${sceneMarkup(true)}</div><div class="title-vignette"></div><header class="title-top"><span class="studio-mark">TRUST ISSUES INC.</span><span class="build-tag"><i></i> MULTIPLAYER OFFICE CHAOS</span></header><div class="title-menu"><div class="title-kicker">A VERY UNPROFESSIONAL GAME</div><h1>OFFICE<span>POLITICS<span class="title-period">.</span></span></h1><p>Do the work. Make some friends.<br>Throw someone under the bus.</p><div class="menu-play"><button class="menu-button menu-primary" data-action="host-menu"><span>${icon('briefcase')} HOST A SHIFT</span>${icon('arrow')}</button><button class="menu-button" data-action="join-menu"><span>${icon('people')} JOIN FRIENDS</span>${icon('arrow')}</button><button class="menu-button menu-practice" data-action="practice"><span>${icon('coffee')} SOLO PRACTICE</span><small>Learn with bots</small></button>${saved?`<button class="continue-button" data-action="resume">${icon('clock')} Continue shift · ${esc(saved.code)}</button>`:''}</div><div class="title-links"><button data-action="rules">How to play</button><span>·</span><button data-action="career">Your career</button></div></div><div class="title-sticker"><b>EVERYONE HAS<br>A SECRET.</b><span>Especially the intern.</span></div><footer class="title-footer"><span>5–10 COLLEAGUES <i>◆</i> ONE QUESTIONABLE WORKPLACE</span><span>WASD / ARROWS · TOUCH CONTROLS</span></footer></section>`;}
function entryModal(join=false){
 openModal('entry',`<span class="eyebrow">${join?'YOUR TEAM IS WAITING':'YOU’RE THE BOSS. FOR NOW.'}</span><h2 id="modal-title">${join?'Clock in.':'Open your office.'}</h2><p>${join?'Enter the room code your friends shared.':'Invite your friends after creating a room. Bots can fill the empty seats.'}</p><form id="${join?'join':'create'}-form"><label for="${join?'join':'host'}-name">YOUR NAME</label><input id="${join?'join':'host'}-name" name="name" maxlength="24" value="${esc(read('op-name',''))}" placeholder="e.g. Alex" required autocomplete="nickname">${join?`<label for="room-code">ROOM CODE</label><input id="room-code" name="code" class="code-input" maxlength="6" minlength="6" value="${esc((new URLSearchParams(location.search).get('room')||'').slice(0,6).toUpperCase())}" placeholder="ABC123" required autocomplete="off">`:`<label for="room-capacity">OFFICE SIZE</label><select id="room-capacity" name="capacity">${[5,6,7,8,9,10].map(n=>`<option value="${n}" ${n===8?'selected':''}>${n} seats</option>`).join('')}</select>`}<button class="button primary" type="submit">${join?'Join the office':'Create my office'} ${icon('arrow')}</button></form>`);$('#'+(join?'join':'host')+'-name')?.focus();
}
function rolePanel(){const me=state.players.find(p=>p.id===state.me.id);return `<section class="role-card ${state.me.faction==='operative'?'operative':''}"><div class="eyebrow">${icon('eye')} YOUR SECRET IDENTITY</div><h3>${!me.alive?'Spectator':state.me.faction==='operative'?'Political Operative':state.phase==='lobby'?'Not assigned yet':'Office Staff'}</h3><p>${state.phase==='lobby'?'Your faction is revealed when the host starts the shift.':esc(state.me.objective)}</p>${state.me.sideObjective?`<div class="side-objective"><b>${state.me.objectiveDone?'✓ Daily objective complete':'Your daily objective'}</b><p>${esc(state.me.sideObjective)}</p></div>`:''}<div class="role-footer"><span>${esc(me.rank)}</span><span>${'♥'.repeat(me.lives)}</span></div></section>`;}
function evidencePanel(){return `<section class="panel"><div class="panel-heading"><h3>The paper trail</h3><span>${state.clues.length} clues</span></div>${state.clues.map(c=>`<div class="clue">${icon('eye')}<div><p>${esc(c.text)}</p><button class="text-button" data-action="pin-clue" data-id="${c.id}">Pin to notebook</button></div></div>`).join('')||'<p class="muted">Clues arrive after work. Until then, watch your colleagues. Suspicion is not proof.</p>'}${state.phase==='incident'?`<button class="button secondary" data-action="influence" ${!state.me.influence||state.me.influenceUsed?'disabled':''}>Run an audit · ${state.me.influence} token(s)</button>`:''}${state.me.rumor?`<div class="notice warning">UNVERIFIED RUMOR<p>${esc(state.me.rumor)}</p></div>`:''}<button class="button secondary" data-action="notebook">${icon('book')} Open private notebook</button></section>`;}
function crewPanel(){return `<section class="panel"><div class="panel-heading"><h3>Your colleagues</h3><span>${state.players.length}/${state.capacity}</span></div>${roster()}${state.phase==='lobby'&&state.hostId===state.me.id&&state.players.length<5?'<button class="button secondary" data-action="fillSeats">Fill empty seats with bots</button>':''}${state.phase==='work'?`<div class="office-network"><button class="button secondary" data-action="give-kudos" ${state.workplace.kudosUsed?'disabled':''}>Give kudos</button><button class="button secondary" data-action="network" ${state.workplace.politicsUsed?'disabled':''}>Build an alliance</button></div>`:''}</section>`;}
function drawerContent(){const me=state.players.find(p=>p.id===state.me.id);switch(drawer){case 'tasks':return state.phase==='work'?phaseContent(me):'<section class="panel"><h3>Off the clock.</h3><p>Personal tasks open during focus time. Finish the current phase first.</p></section>';case 'jobs':return officeBoard()||'<section class="panel"><h3>Inbox zero. For now.</h3><p>Your first client assignments arrive when the shift starts.</p></section>';case 'crew':return crewPanel();case 'role':return rolePanel();case 'evidence':return evidencePanel();case 'project':return projectBoard()||'<section class="panel"><p>Your project will be assigned when the shift begins.</p></section>';case 'phase':return state.phase==='ended'?ending():state.phase==='lobby'?crewPanel():phaseContent(me);default:return '';}}
function gameChat(){const me=state.players.find(p=>p.id===state.me.id);return `<section class="game-chat" aria-label="Office chat"><header><b>${icon('people')} OFFICE CHAT</b><button class="icon-button" data-action="toggle-chat" aria-label="Close chat">${icon('x')}</button></header><div class="office-chat">${state.chat.filter(c=>!muted.has(c.playerId)).slice(-30).map(c=>`<p><b>${esc(c.name)}</b> ${esc(c.text)}</p>`).join('')||'<p class="chat-placeholder">The office is suspiciously quiet.<br>Say something.</p>'}</div>${me.alive||state.phase==='ended'?`<form id="office-chat-form" class="chat-composer"><label class="sr-only" for="office-message">Message your office</label><input id="office-message" name="message" maxlength="240" autocomplete="off" placeholder="Talk to your colleagues…" value="${esc(chatDraft)}" required><button type="submit" aria-label="Send message">${icon('arrow')}</button></form>`:'<p class="spectator-note">Spectators can listen in.</p>'}<div class="reactions">${['👋','😂','☕','🎉','🤔','❤️'].map(text=>`<button data-action="emote" data-text="${text}" aria-label="React ${text}" ${!me.alive&&state.phase!=='ended'?'disabled':''}>${text}</button>`).join('')}</div></section>`;}
function game(){
 const me=state.players.find(p=>p.id===state.me.id),office=state.workplace,ready=state.players.filter(p=>p.ready&&p.connected).length;
 const lobby=state.phase==='lobby',walking=me.alive&&['lobby','briefing','work','ended'].includes(state.phase),complete=state.me.tasks.filter(t=>t.done).length;
 const near=office.stations.find(s=>Math.abs(me.x-s.x)+Math.abs(me.y-s.y)<=1);
 const hasDecision=['incident','meeting','vote','appeal','resolution','ended'].includes(state.phase);
 const currentJob=office.jobs.find(j=>j.ownerId===me.id&&j.status==='in_progress');
 const names={tasks:'YOUR DESK',jobs:'CLIENT ASSIGNMENTS',crew:'THE CREW',role:'SECRET ROLE',evidence:'EVIDENCE',project:'COMPANY PROJECT',phase:state.phase==='ended'?'SHIFT COMPLETE':labels[state.phase]||'THE OFFICE'};
 return `<div class="play-screen"><header class="game-hud"><button class="hud-brand" data-action="game-menu" aria-label="Open game menu">${icon('briefcase')}<span>OFFICE<small>POLITICS</small></span></button><div class="shift-status"><span>${lobby?'WAITING ROOM':state.practice?'PRACTICE · DAY '+state.round:'DAY '+String(state.round).padStart(2,'0')}</span><b>${lobby?'The crew is assembling':labels[state.phase]}</b></div>${state.deadline?`<div class="timer game-timer">${icon('clock')}<span id="countdown">--:--</span></div>`:`<span class="lobby-count">${ready}/${state.players.length} READY</span>`}<div class="hud-actions"><span class="net-status ${connection==='Live'?'online':''}" title="${esc(connection)}"><i></i><span>${esc(connection)}</span></span><button class="room-code" data-action="invite" aria-label="Copy invite link for room ${state.code}">${icon('people')}<span>${state.code}</span></button><button class="icon-button fullscreen-button" data-action="fullscreen" aria-label="Toggle fullscreen">⛶</button><button class="icon-button" data-action="game-menu" aria-label="Game menu">${icon('grid')}</button></div></header><div class="player-hud"><div class="player-identity">${character(state.players.indexOf(me))}<span><b>${esc(me.name)}</b><small>${me.alive?esc(me.designation):'SPECTATING'}</small></span><span class="player-hearts" aria-label="${me.lives} lives">${me.alive?'♥'.repeat(me.lives)+'♡'.repeat(2-me.lives):'◉'}</span></div><button class="company-meter" data-action="panel" data-panel="project"><span>COMPANY HEALTH <b>${state.progress}%</b></span><i><em style="width:${state.progress}%"></em></i></button><div class="player-resources"><span title="Energy">⚡ <b>${office.energy}/3</b></span><span title="Reputation">★ <b>${office.reputation}</b></span><span title="Coffee collected">☕ <b>${me.coffee}</b></span></div></div><section class="game-viewport" aria-label="Office play area">${sceneMarkup()}<div class="world-caption">FLOOR 01 <span>◆</span> TRUST ISSUES INC.</div>${!lobby&&state.phase!=='ended'?`<button class="mission-tracker" data-action="panel" data-panel="${currentJob?'jobs':'tasks'}"><span>YOUR NEXT MOVE <b>${complete}/3</b></span><strong>${currentJob?esc(currentJob.task?.title||office.jobs.find(j=>j.id===currentJob.id)?.task.title):state.phase==='work'?'Get some actual work done.':state.phase==='briefing'?'Read your role. Trust nobody.':'Keep your story straight.'}</strong><small>${currentJob?'Deliver at '+esc(office.stations.find(s=>s.id===currentJob.station)?.name):state.phase==='work'?'Open your desk or claim a client assignment.':'Open the phase panel for your next action.'}</small></button>`:''}${lobby?`<div class="lobby-overlay"><span class="eyebrow">YOUR OFFICE IS OPEN</span><h2>Good colleagues.<br>Questionable intentions.</h2><p>${state.players.length<5?'Invite your friends or fill the empty seats with bots.':'Explore the office while everyone readies up.'}</p><div class="lobby-faces">${state.players.map((p,i)=>`<span title="${esc(p.name)}" class="${p.ready?'is-ready':''}">${character(i)}<i>${p.ready?'✓':'…'}</i></span>`).join('')}</div><div class="lobby-buttons"><button class="button ${me.ready?'secondary':'primary'}" data-action="ready">${me.ready?'✓ Ready!':'I’m ready'}</button>${state.hostId===me.id?`<button class="button primary" data-action="start" ${state.players.length<5||ready!==state.players.length?'disabled':''}>Start shift ${icon('arrow')}</button>`:''}</div>${state.hostId===me.id&&state.players.length<5?'<button class="text-button" data-action="fillSeats">+ Fill empty seats with bots</button>':''}</div>`:''}${state.phase==='briefing'?`<button class="shift-banner" data-action="panel" data-panel="role"><span>THE SHIFT BEGINS</span><b>You have a secret identity.</b><small>Tap to reveal your role ${icon('arrow')}</small></button>`:''}<div class="touch-controls" aria-label="Movement controls">${[['up','↑'],['left','←'],['down','↓'],['right','→']].map(([d,label])=>`<button data-action="walk" data-direction="${d}" aria-label="Move ${d}" ${walking?'':'disabled'}>${label}</button>`).join('')}</div><div class="world-bottom"><span class="keyboard-hint"><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> MOVE <i>·</i> <kbd>E</kbd> INTERACT</span>${near&&walking?`<button class="interact-button" data-action="station" data-id="${near.id}"><kbd>E</kbd> ${near.id==='kitchen'?'Take a break':esc(near.name)}</button>`:''}</div><button class="mini-map" data-action="map-view" aria-label="${mapOverview?'Follow my character':'Show whole office'}" aria-pressed="${mapOverview}"><svg viewBox="0 0 120 80" aria-hidden="true"><rect x="1" y="1" width="118" height="78" rx="3" fill="#445b5e"/>${[2,5].flatMap(y=>[2,3,8,9].map(x=>`<rect x="${x*10}" y="${y*10}" width="9" height="8" rx="1" fill="#b29878"/>`)).join('')}${state.players.filter(p=>p.connected).map(p=>`<circle cx="${p.x*10+5}" cy="${p.y*10+5}" r="${p.id===me.id?3.5:2}" fill="${p.id===me.id?'#ffcd74':'#b2d9cc'}"/>`).join('')}</svg><span>${mapOverview?'FOLLOW PLAYER':'OFFICE MAP'}</span></button></section><nav class="game-hotbar" aria-label="Game controls">${[['tasks','briefcase','Desk','T'],['jobs','inbox','Workboard','J'],['crew','people','Crew','P'],['evidence','eye','Evidence','I'],['role','shield','My role','R']].map(([panel,symbol,title,key])=>`<button class="hotbar-item ${drawer===panel?'active':''}" data-action="panel" data-panel="${panel}" aria-pressed="${drawer===panel}">${icon(symbol)}<span>${title}</span><kbd>${key}</kbd>${panel==='jobs'&&office.jobs.some(j=>j.status==='review')?'<i class="notification-dot"></i>':''}</button>`).join('')}<button class="hotbar-item ${chatOpen?'active':''}" data-action="toggle-chat" aria-pressed="${chatOpen}">${icon('people')}<span>Chat</span><kbd>C</kbd>${state.chat.length?`<i class="chat-count">${Math.min(99,state.chat.filter(c=>!muted.has(c.playerId)).length)}</i>`:''}</button>${hasDecision?`<button class="phase-action" data-action="panel" data-panel="phase">${icon(state.phase==='vote'?'shield':'people')}<span>${state.phase==='vote'?'Cast your vote':state.phase==='ended'?'Results':'Meeting room'}</span></button>`:''}${state.practice&&state.phase!=='lobby'&&state.phase!=='ended'?'<button class="practice-next" data-action="nextPhase" title="Advance practice phase">Next phase →</button>':''}</nav>${drawer?`<aside class="game-drawer" aria-label="${esc(names[drawer])}"><header><div><span>OFFICE TERMINAL</span><h2>${esc(names[drawer])}</h2></div><button class="icon-button" data-action="close-panel" aria-label="Close panel">${icon('x')}</button></header><div class="game-drawer-body">${drawerContent()}</div></aside>`:''}${chatOpen?gameChat():''}</div>`;
}
function gameMenu(){openModal('menu',`<span class="eyebrow">TAKE A BREATHER</span><h2 id="modal-title">Still on the clock.</h2><p>The multiplayer shift keeps running while this menu is open.</p><div class="pause-menu"><button class="button primary" data-action="close">Back to the office</button><button class="button secondary" data-action="rules">How to play</button><button class="button secondary" data-action="career">Career & achievements</button>${state.phase!=='lobby'?'<button class="button secondary" data-action="notebook">Private notebook</button>':''}<button class="button secondary" data-action="fullscreen">Toggle fullscreen</button><button class="button secondary" data-action="invite">Copy invite link</button><button class="button danger" data-action="leave">Leave office</button></div>`);}
function interactStation(id){
 const station=state.workplace.stations.find(s=>s.id===id);if(!station)return;
 const me=state.players.find(p=>p.id===state.me.id),near=Math.abs(me.x-station.x)+Math.abs(me.y-station.y)<=1;
 if(id==='kitchen'){if(!near)return toast('Walk over to the break room first.');if(state.phase!=='work')return toast('Breaks open during focus time.');return act('takeBreak');}
 const job=state.workplace.jobs.find(j=>j.station===id&&j.ownerId===me.id&&j.status==='in_progress');
 if(near&&job&&state.phase==='work')return jobModal(job.id);
 selectedStation=id;drawer='jobs';render();
}

function practiceModal(){openModal('practice',`<div class="card-icon lavender">${icon('people')}</div><h2 id="modal-title">Your practice office</h2><p>Five simulated colleagues will work, discuss, sabotage, and vote. They make mistakes and use public evidence. You can advance phases whenever you’re ready.</p><form id="practice-form"><label for="practice-name">Your name</label><input id="practice-name" name="name" maxlength="24" value="${esc(read('op-name',''))}" placeholder="Alex" required><label for="practice-faction">Your private faction</label><select id="practice-faction" name="faction"><option value="staff">Office Staff · learn to investigate</option><option value="operative">Political Operative · practice sabotage</option><option value="random">Surprise me</option></select><button class="button primary" type="submit">Clock in ${icon('arrow')}</button></form>`);}
function projectBoard(){if(!state.project)return '';return `<section class="panel project-board"><div class="panel-heading"><h3>${icon(state.project.icon)} ${esc(state.project.title)}</h3><span>WORKDAY ${state.round}</span></div><p>${esc(state.project.description)}</p><div class="daily-event"><b>${esc(state.officeEvent.title)}</b><span>${esc(state.officeEvent.description)}</span></div><div class="project-milestone"><b>${state.goal.awarded?'✓ Team milestone reached':'Shared milestone'}</b><span>${state.goal.completed} / ${state.goal.target} contributions</span></div><div class="progress-bar"><i style="width:${Math.min(100,state.goal.completed/state.goal.target*100)}%"></i></div><p class="muted">Reach the milestone: +8% company progress and 1 influence token for every active colleague.</p></section>`;}
function recommendations(){return `<details class="recommendations"><summary>Recommend a colleague for review</summary><p>A public suggestion, not a ballot. Simulated colleagues consider this alongside the evidence.</p><div class="recommendation-options">${state.players.filter(p=>p.alive&&p.connected&&p.id!==state.me.id).map(p=>`<button class="button secondary" data-action="recommend" data-id="${p.id}" ${state.me.recommended?'disabled':''}>${esc(p.name)}</button>`).join('')}</div></details>`;}
function getNote(){const all=read('op-notes',{});return all?.[state.matchId+':'+state.me.id]||{text:'',clues:[]};}
function saveNote(note){const all=read('op-notes',{});all[state.matchId+':'+state.me.id]=note;save('op-notes',Object.fromEntries(Object.entries(all).slice(-20)));}
function notebook(){const note=getNote();openModal('notebook',`<div class="card-icon lavender">${icon('inbox')}</div><span class="eyebrow">PRIVATE · SAVED ONLY IN YOUR BROWSER</span><h2 id="modal-title">Your case notes</h2><label for="private-notes">Suspicions, observations, and questions</label><textarea id="private-notes" maxlength="2000" rows="7" placeholder="What does the evidence actually tell you?">${esc(note.text)}</textarea><small>Saved as you type. Never shared with other players.</small><h3>Pinned evidence</h3>${note.clues.length?note.clues.map(c=>`<div class="notice"><b>Workday ${c.day}</b><p>${esc(c.text)}</p></div>`).join(''):'<p>Use “Save to notebook” on a clue to keep it across workdays.</p>'}`);}
document.addEventListener('input',e=>{if(e.target.id==='private-notes'&&state){const note=getNote();note.text=e.target.value;saveNote(note);}});
function career(){stats=normalizeStats(read('op-stats',stats));const level=Math.floor(stats.xp/100)+1;openModal('career',`<div class="card-icon lavender">${icon('trophy')}</div><span class="eyebrow">YOUR LOCAL CAREER · LEVEL ${level}</span><h2 id="modal-title">Every shift tells a story.</h2><div class="career-stats"><div><b>${stats.matches}</b><span>matches</span></div><div><b>${stats.tasks}</b><span>tasks completed</span></div><div><b>${stats.correct}</b><span>correct votes</span></div><div><b>${stats.xp}</b><span>career XP</span></div></div><p>${100-stats.xp%100} XP until level ${level+1}. Match career rank remains separate from this lifetime level.</p><h3>Achievements · ${ACHIEVEMENTS.filter(a=>stats[a.key]>=a.target).length} / ${ACHIEVEMENTS.length}</h3><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<div class="achievement ${stats[a.key]>=a.target?'unlocked':''}">${icon(stats[a.key]>=a.target?'trophy':'shield')}<div><b>${a.title}</b><p>${a.description}</p><small>${Math.min(stats[a.key],a.target)} / ${a.target} · ${stats[a.key]>=a.target?'Unlocked':'In progress'}</small></div></div>`).join('')}</div><h3>Recent shifts</h3>${stats.history.length?stats.history.map(h=>`<div class="history-row"><div><b>${esc(h.project)}</b><span>${esc(h.mode)} · ${esc(h.rank)} · ${esc(h.days)} day(s)</span></div><div><b>${esc(h.xp)} XP</b><span>${esc(h.tasks)} tasks · ${esc(h.ending==='staff'?'Staff victory':h.ending==='abandoned'?'Abandoned':'Two survivors')}</span></div></div>`).join(''):'<p>Finish a match to start your history.</p>'}<button class="button secondary" data-action="export-career">Export career as JSON ${icon('arrow')}</button>`);}
function roster(showVotes=false) { return state.players.map((p,i)=>`<div class="person ${!p.alive?'eliminated':''}">${avatar(p,i)}<div class="person-info"><b>${esc(p.name)} ${p.id===state.me.id?'<small>(you)</small>':''} ${p.id===state.hostId?'<span class="host-mark">HOST</span>':''}</b><span>${esc(p.designation)}</span></div>${state.phase==='lobby'?`<span class="status ${p.connected&&p.ready?'ready':''}">${!p.connected?'Reconnecting':p.ready?'Ready':'Getting settled'}</span>`:`<div class="lives" aria-label="${p.lives} lives">${p.alive?'♥'.repeat(p.lives)+'♡'.repeat(2-p.lives):'Spectating'}</div>${p.id!==state.me.id?`<button class="mute-button" data-action="mute" data-id="${p.id}" aria-label="${muted.has(p.id)?'Unmute':'Mute'} ${esc(p.name)}">${muted.has(p.id)?'Unmute':'Mute'}</button>`:''}`}</div>`).join(''); }
const phases=['briefing','work','incident','meeting','vote','resolution'];
const labels={briefing:'Morning briefing',work:'Focus time',incident:'Incident report',meeting:'Team meeting',vote:'The ballot',appeal:'HR appeal',resolution:'Performance review',ended:'End of the workday'};
function phaseContent(me){
 const active=me.alive;
 if(state.phase==='briefing') return `<section class="panel briefing"><div class="card-icon lavender">${icon('coffee')}</div><span class="eyebrow">TODAY’S SHARED PROJECT</span><h2>${esc(state.project.title)}</h2><p>${esc(state.project.description)} Watch for unexplained setbacks.</p><div class="briefing-facts"><div><b>${state.players.filter(p=>p.alive).length}</b><span>at their desks</span></div><div><b>${state.workSeconds} sec</b><span>to get work done</span></div><div><b>2 lives</b><span>at the start</span></div></div><div class="notice">Open “My role” to reveal your secret identity. Work begins automatically when the timer ends.</div></section>`;
 if(state.phase==='work') return `<section class="panel"><div class="panel-heading"><h3>Your desk</h3><span>${state.me.tasks.filter(t=>t.done).length} / ${state.me.tasks.length} complete</span></div>${!active?'<p class="muted">Your colleagues are at work. The incident report will be shared shortly.</p>':state.me.tasks.map(t=>`<button class="task-card ${t.done?'done':''}" data-action="task" data-id="${t.id}" ${t.done?'disabled':''}><span class="card-icon ${t.done?'sage':'lavender'}">${icon(t.done?'check':t.icon)}</span><span><small>${esc(t.category)}</small><b>${esc(t.title)}</b><span>${t.done?'Filed. Nice work.':'A quick contribution · +'+state.officeEvent.taskPoints+'% progress'}</span></span>${icon(t.done?'check':'arrow')}</button>`).join('')}${state.fileMissing?`<div class="notice warning">A project document is missing.<button class="text-button" data-action="restore" ${!active?'disabled':''}>Restore the shared file ${icon('arrow')}</button></div>`:''}</section>${active&&state.me.faction==='operative'?`<section class="panel sabotage"><div class="panel-heading"><h3>A little interference</h3><span>PRIVATE</span></div><p>One action per workday. Every disruption can leave a clue.</p><div class="sabotage-actions">${state.catalog.actions.map((a,i)=>`<button class="button secondary" data-action="sabotage" data-index="${i}" ${state.me.actionUsed?'disabled':''}>${icon('bolt')}${a}</button>`).join('')}</div>${state.me.actionUsed?'<p class="muted">Your move is made. Keep up appearances.</p>':''}</section>`:''}`;
 if(state.phase==='incident')return `<section class="panel briefing"><div class="card-icon peach">${icon('eye')}</div><h2>Something to talk about.</h2><p>The paper trail is in. Read the clues before the team meeting. Access logs point to possibilities, not proof.</p><div class="notice">${state.fileMissing?'A project file is still missing.':'Project status has been recorded.'} A failed task doesn’t automatically mean sabotage.</div></section>`;
 if(state.phase==='meeting')return `<section class="panel"><div class="panel-heading"><h3>The conference room</h3><span>Quick discussion prompts</span></div><div class="chat-log" aria-live="polite">${state.chat.filter(c=>c.round===state.round&&!muted.has(c.playerId)).map(c=>`<div class="chat-message"><b>${esc(c.name)}</b><div><p>${esc(c.text)}</p><button class="text-button" data-action="pin-clue" data-id="${c.id}">Save to notebook</button></div></div>`).join('')||'<div class="chat-empty">The room is quiet.<br>Someone has to break the ice.</div>'}</div>${active?`${recommendations()}<div class="prompt-grid">${state.catalog.prompts.map((p,i)=>`<button data-action="chat" data-index="${i}">${esc(p)}</button>`).join('')}</div>`:'<p class="muted">Spectators can read the discussion but cannot participate.</p>'}</section>`;
 if(state.phase==='vote')return `<section class="panel"><div class="panel-heading"><h3>Who’s working against the team?</h3>${icon('shield')}</div><p class="muted">Ballots stay private until the timer ends. More than half of connected active players must agree.</p>${!active?'<div class="notice">Voting is in progress. Results will appear together.</div>':state.me.voted?'<div class="ballot-sent">'+icon('check')+'<h3>Your ballot is sealed.</h3><p>Take a breath. The results will be revealed together.</p></div>':`<div class="vote-options">${state.players.filter(p=>p.alive&&p.connected&&p.id!==me.id).map((p,i)=>`<button class="vote-option ${voteTarget===p.id?'selected':''}" data-action="select-vote" data-id="${p.id}">${avatar(p,i)}<b>${esc(p.name)}</b>${icon(voteTarget===p.id?'check':'people')}</button>`).join('')}<button class="vote-option ${voteTarget==='abstain'?'selected':''}" data-action="select-vote" data-id="abstain">${icon('shield')}<b>Abstain · not enough evidence</b></button></div><button class="button primary" data-action="vote" ${!voteTarget?'disabled':''}>Submit private ballot ${icon('arrow')}</button>`}</section>`;
 if(state.phase==='appeal'){const accused=state.players.find(p=>p.id===state.accused);return `<section class="panel briefing"><div class="card-icon peach">${icon('briefcase')}</div><span class="eyebrow">HUMAN RESOURCES · CASE ${state.round}</span><h2>${esc(accused.name)} has the floor.</h2><p>The accusation was incorrect. An HR appeal can protect their remaining lives.</p>${state.explanation?`<blockquote>“${esc(state.explanation)}”</blockquote>${active&&me.id!==accused.id&&!state.me.appealVoted?'<div class="appeal-buttons"><button class="button primary" data-action="accept">Accept appeal</button><button class="button secondary" data-action="reject">Reject appeal</button></div>':'<div class="notice">Waiting for the appeal ballots. A tie causes no life loss.</div>'}`:me.id===accused.id?`<p>Choose your once-per-match explanation before the timer runs out.</p>${explanations.map((e,i)=>`<button class="button secondary appeal-option" data-action="appeal" data-index="${i}">${e}</button>`).join('')}`:'<div class="notice">Waiting for the employee’s explanation.</div>'}</section>`;}
 return `<section class="panel briefing"><div class="card-icon sage">${icon('receipt')}</div><h2>${esc(state.result?.title)}</h2><p>${esc(state.result?.text)}</p>${ballots()}<div class="notice">The next workday begins automatically.</div></section>`;
}
function ballots(){ return state.result?.ballots?`<details class="ballots"><summary>View the revealed ballots</summary>${state.result.ballots.map(b=>`<div><span>${esc(b.voter)}</span>${icon('arrow')}<b>${esc(b.target)}</b></div>`).join('')}</details>`:''; }
function ending(){ return `<section class="ending panel"><div class="card-icon ${state.ending==='staff'?'sage':'lavender'}">${icon(state.ending==='staff'?'shield':'briefcase')}</div><span class="eyebrow">THE OFFICE IS CLOSED</span><h1>${state.ending==='staff'?'Trust helped this team succeed.':state.ending==='abandoned'?'The meeting was adjourned.':'Nobody wins this kind of politics.'}</h1><p>${state.ending==='staff'?'Office Staff identified every Political Operative. The team can finally get back to work.':state.ending==='abandoned'?'Too many colleagues left the office to continue. Gather the team and try again.':'The company that plays office politics never truly wins. It only breaks trust, harms people’s futures, and eventually destroys itself.'}</p>${state.result?`<div class="notice">${esc(state.result.title)}</div>`:''}<div class="final-roster">${state.players.map((p,i)=>`<div class="person">${avatar(p,i)}<div class="person-info"><b>${esc(p.name)}</b><span>${p.faction==='operative'?'Political Operative':'Office Staff'}</span></div><span class="pill">${esc(p.rank)}</span></div>`).join('')}</div>${ballots()}<div class="ending-buttons">${state.hostId===state.me.id?'<button class="button primary" data-action="rematch">Play again '+icon('arrow')+'</button>':'<p class="muted">Your host can reopen the lobby for another match.</p>'}<button class="button secondary" data-action="leave">Back to overview</button></div><span class="save-note">Career stats and match history saved in this browser. <button class="text-button" data-action="career">View achievements and career</button></span></section>`;}
let chatDraft = '', lastStep = 0, walkBusy=false, heldWalk=null, heldWalkTimer=null, ignoreWalkClickUntil=0;
function officeBoard(){
 const office=state.workplace;if(!office||['lobby','ended'].includes(state.phase))return '';
 const me=state.players.find(p=>p.id===state.me.id), active=me.alive&&state.phase==='work';
 const name=id=>state.players.find(p=>p.id===id)?.name||'Unassigned';
 const station=id=>office.stations.find(s=>s.id===id)?.name||id;
 return `<section class="panel office-board"><div class="panel-heading"><h3>${selectedStation?esc(office.stations.find(s=>s.id===selectedStation)?.name):'Client workboard'}</h3><span>Claim → deliver → review</span></div>${selectedStation?'<button class="text-button" data-action="all-jobs">← All assignments</button>':''}<div class="office-metrics"><span>⚡ Energy <b>${office.energy}/3</b></span><span>⭐ Reputation <b>${office.reputation}</b></span><span>🌱 Team morale <b>${office.morale}%</b></span></div><p class="muted">Each signed-off client assignment adds 6% company progress. Deliver at its office station; a different colleague checks your work. Deadlines cost morale, not lives.</p><div class="assignment-grid">${(selectedStation?office.jobs.filter(j=>j.station===selectedStation):office.jobs).map(j=>`<article class="assignment ${j.status}"><div class="assignment-meta"><span>${esc(j.task.category)}</span><span>${({open:'Available',in_progress:'In progress',review:'Needs review',done:'Delivered'})[j.status]}</span></div><h3>${esc(j.task.title)}</h3><p>📍 ${esc(station(j.station))}</p><small>Owner: ${esc(name(j.ownerId))}${j.reviewerId?' · Reviewed by '+esc(name(j.reviewerId)):''}</small>${active?`<div class="assignment-actions">${j.status==='open'?`<button class="button secondary" data-action="claim-job" data-id="${j.id}">Claim assignment</button>`:''}${j.status==='in_progress'&&j.ownerId===me.id?`<button class="button primary" data-action="open-job" data-id="${j.id}">Read brief & deliver</button><button class="text-button" data-action="handoff-job" data-id="${j.id}">Hand off to a colleague</button>`:''}${j.status==='review'&&j.ownerId!==me.id?`<button class="button primary" data-action="review-job" data-id="${j.id}">Review & sign off</button>`:''}${j.status==='review'&&j.ownerId===me.id?'<span class="pill">Waiting for a second pair of eyes</span>':''}${j.status==='done'&&j.ownerId!==me.id&&!office.politicsUsed?`<button class="text-button" data-action="steal-credit" data-id="${j.id}">Claim the spotlight · −5 morale</button>`:''}</div>`:''}</article>`).join('')}</div><div class="office-network"><button class="button secondary" data-action="take-break" ${!active||office.breakUsed?'disabled':''}>☕ Take a break · +2 energy</button><button class="button secondary" data-action="give-kudos" ${!active||office.kudosUsed?'disabled':''}>👏 Give kudos</button><button class="button secondary" data-action="network" ${!active||office.politicsUsed?'disabled':''}>🤝 Build an alliance</button></div><small>Breaks require being next to the break room. Kudos and politics: once per workday. Reputation is public; it does not reveal anyone’s faction.</small><details class="office-feed"><summary>Office paper trail · ${office.activity.length} updates</summary>${office.activity.slice(-12).reverse().map(e=>`<p><small>DAY ${e.round}</small> ${esc(e.text)}</p>`).join('')}</details></section>`;
}
function currentPuzzle(){return modal?.type==='job'?state.workplace.jobs.find(j=>j.id===modal.id)?.task:state.me.tasks.find(t=>t.id===modal?.id);}
function jobModal(id,review=false){
 const job=state.workplace.jobs.find(j=>j.id===id);if(!job)return;
 const t=job.task;taskAnswer=t.kind==='order'?t.options.map((_,i)=>i):[];
 openModal('job',`<span class="eyebrow">${review?'PEER REVIEW · SECOND PAIR OF EYES':'CLIENT ASSIGNMENT'}</span><h2 id="modal-title">${esc(t.title)}</h2><p>${esc(t.instruction)}</p>${review?'<p class="muted">Check the brief independently before you sign off. You share the reputation reward.</p>':`<p class="muted">Deliver next to ${esc(state.workplace.stations.find(s=>s.id===job.station)?.name)}. Costs 1 energy.</p>`}<div id="task-options"></div><button class="button primary" data-action="submit-job" data-review="${review}">${review?'Sign off the assignment':'Send for peer review'}</button>`,id);renderTask();
}
function colleaguePicker(action,jobId=''){
 openModal('colleague',`<h2 id="modal-title">${action==='kudos'?'Recognize a colleague':action==='network'?'Build an office alliance':'Hand over the assignment'}</h2><p>${action==='kudos'?'They gain 2 reputation. The office gains 2 morale.':action==='network'?'You each gain 1 reputation. One politics move per day.':'A clear handover helps the team meet its deadline.'}</p>${state.players.filter(p=>p.id!==state.me.id&&p.alive&&p.connected).map(p=>`<button class="button secondary appeal-option" data-action="choose-colleague" data-kind="${action}" data-job="${jobId}" data-id="${p.id}">${esc(p.name)} · ${p.reputation} reputation</button>`).join('')}`);
}

async function walk(direction){
 const steps={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
 if(!state||!steps[direction]||walkBusy||Date.now()-lastStep<170)return;
 const me=state.players.find(p=>p.id===state.me.id);
 if(!me?.alive||!['lobby','briefing','work','ended'].includes(state.phase))return;
 const [dx,dy]=steps[direction],x=me.x+dx,y=me.y+dy;
 if(x<0||x>11||y<0||y>7||([2,3,8,9].includes(x)&&[2,5].includes(y)))return;
 lastStep=Date.now();walkBusy=true;
 try{await act('move',{dx,dy});}finally{walkBusy=false;}
}
function stopHeldWalk(){if(heldWalk)ignoreWalkClickUntil=Date.now()+500;heldWalk=null;clearInterval(heldWalkTimer);}
document.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-action="walk"]');if(!button||button.disabled||e.pointerType==='mouse')return;e.preventDefault();stopHeldWalk();heldWalk=button.dataset.direction;walk(heldWalk);heldWalkTimer=setInterval(()=>{if(heldWalk)walk(heldWalk);},180);});
document.addEventListener('pointerup',stopHeldWalk);
document.addEventListener('pointercancel',stopHeldWalk);
window.addEventListener('blur',stopHeldWalk);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopHeldWalk();});
document.addEventListener('input',e=>{if(e.target.id==='office-message')chatDraft=e.target.value;});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='office-chat-form')return;e.preventDefault();
 const text=chatDraft; if(await act('say',{text})){if(chatDraft===text)chatDraft='';render();$('#office-message')?.focus();}
});
document.addEventListener('keydown',e=>{
 if(!state||modal)return;
 if(e.key==='Escape'){drawer=null;chatOpen=false;render();return;}
 if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable]'))return;
 if(e.key==='Enter'||e.key===' ')return;
 const shortcut={t:'tasks',j:'jobs',p:'crew',i:'evidence',r:'role'}[e.key.toLowerCase()];
 if(shortcut){e.preventDefault();if(e.repeat)return;drawer=drawer===shortcut?null:shortcut;selectedStation=null;render();return;}
 if(e.key.toLowerCase()==='c'){e.preventDefault();if(e.repeat)return;chatOpen=!chatOpen;render();if(chatOpen)$('#office-message')?.focus();return;}
 if(e.key.toLowerCase()==='e'){e.preventDefault();const me=state.players.find(p=>p.id===state.me.id);const near=state.workplace.stations.find(s=>Math.abs(me.x-s.x)+Math.abs(me.y-s.y)<=1);if(near)interactStation(near.id);return;}

 const direction={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'}[e.key];
 if(direction&&['lobby','briefing','work','ended'].includes(state.phase)){e.preventDefault();walk(direction);}
});

function render(){
 const focused=document.activeElement,typing=focused?.id==='office-message',caret=typing?focused.selectionStart:null;
 const scene=$('.scene-world'),sameScene=scene&&scene.dataset.room===(state?.code||'title');
 const log=$('.office-chat'),chatBottom=!log||log.scrollHeight-log.scrollTop-log.clientHeight<30,chatScroll=log?.scrollTop||0;
 const panel=$('.game-drawer-body'),panelScroll=panel?.scrollTop||0,panelKind=panel?.parentElement.dataset.panel;
 const focusAction=focused?.closest('#app')&&focused.dataset.action?{...focused.dataset}:null;
 $('#app').innerHTML=shell(state?game():landing());
 const freshScene=$('.scene-world');if(sameScene)freshScene.replaceWith(scene);$('.scene-world').dataset.room=state?.code||'title';
 if(state){const newPanel=$('.game-drawer');if(newPanel){newPanel.dataset.panel=drawer;if(panelKind===drawer)newPanel.querySelector('.game-drawer-body').scrollTop=panelScroll;}}
 updateScene(state||demoOffice,{overview:mapOverview,preview:!state});
 if(typing){const input=$('#office-message');input?.focus({preventScroll:true});input?.setSelectionRange(caret,caret);}
 else if(focusAction){const target=[...document.querySelectorAll('#app [data-action]')].find(el=>Object.entries(focusAction).every(([k,v])=>el.dataset[k]===v));target?.focus({preventScroll:true});}
 const nextLog=$('.office-chat');if(nextLog)nextLog.scrollTop=chatBottom?nextLog.scrollHeight:chatScroll;
 updateClock();
}
window.addEventListener('resize',()=>updateScene(state||demoOffice,{overview:mapOverview,preview:!state}));
function updateClock(){ const el=$('#countdown'); if(el&&state?.deadline){const sec=Math.max(0,Math.ceil((state.deadline-Date.now()-offset)/1000));el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;el.parentElement.classList.toggle('urgent',sec<11);}}
setInterval(updateClock,250);
let previousFocus;
function openModal(type, content, id=null){ previousFocus=document.activeElement; modal={type,id}; $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Close dialog">${icon('x')}</button>${content}</section></div>`; $('.modal button, .modal input')?.focus(); }
function closeModal(){ modal=null; $('#modal-root').innerHTML=''; previousFocus?.focus(); }
function taskModal(id){const t=state.me.tasks.find(x=>x.id===id); if(!t||t.done)return; taskAnswer=t.kind==='order'?t.options.map((_,i)=>i):[]; openModal('task',`<div class="card-icon lavender">${icon(t.icon)}</div><span class="eyebrow">${esc(t.category)} · YOUR CONTRIBUTION</span><h2 id="modal-title">${esc(t.title)}</h2><p>${esc(t.instruction)}</p><div id="task-options"></div><button class="button primary" data-action="submit-task">Submit your work ${icon('arrow')}</button>`,id);renderTask();}
function renderTask(){const t=currentPuzzle();if(!t)return;$('#task-options').innerHTML=t.kind==='choice'?t.options.map((o,i)=>`<button class="answer-option ${taskAnswer[0]===i?'selected':''}" data-action="answer" data-index="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join(''):taskAnswer.map((n,i)=>`<div class="order-option"><span class="order-number">0${i+1}</span><b>${esc(t.options[n])}</b><button data-action="move-up" data-index="${i}" aria-label="Move ${esc(t.options[n])} up" ${i===0?'disabled':''}>↑</button><button data-action="move-down" data-index="${i}" aria-label="Move ${esc(t.options[n])} down" ${i===taskAnswer.length-1?'disabled':''}>↓</button></div>`).join('');}
function rules(){openModal('rules',`<span class="eyebrow">EMPLOYEE HANDBOOK / FIRST EDITION</span><h2 id="modal-title">Welcome to Office Politics.</h2><p>Play with 5–10 people, or start a solo practice office with 5 simulated colleagues. Practice lets you choose a faction and advance phases at your own pace.</p><ol class="rules-list"><li><b>Clock in.</b> Everyone readies up, then the host starts. A secret faction is assigned independently of your job title.</li><li><b>Do the work.</b> Work through 36 task types across 6 rotating projects. Office events change task rewards. Complete the shared milestone for +8% progress and a team influence token. Operatives can use one sabotage action each day.</li><li><b>Read the room.</b> Review clues, save evidence in your private notebook, then discuss using office chat, quick prompts, and a public recommendation. Clues are ambiguous; missed work is not proof.</li><li><b>Cast your ballot.</b> One private vote per day. A strict majority eliminates an operative; correct voters get promoted. Ties and abstentions cause no penalty.</li><li><b>Make your case.</b> An innocent accused colleague gets one HR appeal per match. Accepting or tying saves their life; rejection costs one. At zero lives, they spectate.</li><li><b>Find your ending.</b> Staff wins if all operatives are found. If two people remain, no individual wins. Politics has cost the whole company.</li></ol><div class="notice">Names, reconnect details, and completed-match career stats are saved locally. Every action is saved in the database and shared with your colleagues. Disconnected seats are held for 30 seconds.</div>`);}
document.addEventListener('submit',async e=>{if(!['create-form','join-form','practice-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));const button=form.querySelector('button');button.disabled=true;try{save('op-name',data.name.trim());if(data.capacity)data.capacity=Number(data.capacity);if(data.code)data.code=data.code.trim().toUpperCase();const session=await api(form.id==='create-form'?'create':form.id==='practice-form'?'practice':'join',data);saved=session;save('op-session',session);closeModal();connect(session.token);}catch(error){toast(error.message);button.disabled=false;}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action, id=b.dataset.id, n=Number(b.dataset.index);
 if(a==='host-menu'||a==='join-menu')return entryModal(a==='join-menu');
 if(a==='game-menu')return gameMenu();
 if(a==='panel'){drawer=drawer===b.dataset.panel?null:b.dataset.panel;if(drawer&&innerWidth<761)chatOpen=false;selectedStation=null;render();return;}
 if(a==='close-panel'){drawer=null;render();return;}
 if(a==='all-jobs'){selectedStation=null;render();return;}
 if(a==='toggle-chat'){chatOpen=!chatOpen;if(chatOpen&&innerWidth<761)drawer=null;render();if(chatOpen)$('#office-message')?.focus();return;}
 if(a==='map-view'){mapOverview=!mapOverview;render();return;}
 if(a==='station')return interactStation(id);
 if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Fullscreen is not available in this browser.');}catch{toast('Fullscreen is not available in this browser.');}return;}
 if(a==='invite'){const link=new URL('/',location.origin);link.searchParams.set('room',state.code);try{await navigator.clipboard.writeText(link.href);toast('Invite link copied. Send it to your friends.');}catch{openModal('invite',`<h2 id="modal-title">Invite your colleagues</h2><input aria-label="Invite link" readonly value="${esc(link.href)}">`);}return;}
 if(a==='claim-job')return act('claimJob',{id});
 if(a==='open-job'||a==='review-job')return jobModal(id,a==='review-job');
 if(a==='handoff-job')return colleaguePicker('handoff',id);
 if(a==='give-kudos'||a==='network')return colleaguePicker(a==='network'?'network':'kudos');
 if(a==='take-break')return act('takeBreak');
 if(a==='steal-credit')return act('officePolitics',{move:'credit',id});
 if(a==='choose-colleague'){const kind=b.dataset.kind;const ok=await act(kind==='handoff'?'handoffJob':kind==='network'?'officePolitics':'kudos',{target:id,id:b.dataset.job,move:'network'});if(ok)closeModal();return;}
 if(a==='submit-job'){if(!taskAnswer.length)return toast('Choose your answer first.');b.disabled=true;if(await act(b.dataset.review==='true'?'reviewJob':'submitJob',{id:modal.id,answer:taskAnswer})){closeModal();toast('The workboard has been updated.');}else b.disabled=false;return;}
 if(a==='walk'){if(Date.now()>=ignoreWalkClickUntil)return walk(b.dataset.direction);return;}if(a==='emote')return act('emote',{text:b.dataset.text});
 if(a==='rules')return rules();if(a==='close')return closeModal();if(a==='career')return career();
 if(a==='practice')return practiceModal();
 if(a==='notebook')return notebook();
 if(a==='pin-clue'){const clue=state.clues.find(c=>c.id===id);if(clue){const note=getNote();if(!note.clues.some(c=>c.id===id)){note.clues.push({id,text:clue.text,day:state.round});saveNote(note);}toast('Evidence saved to your private notebook.');}return;}
 if(a==='recommend')return act('recommend',{target:id});
 if(a==='export-career'){const blob=new Blob([JSON.stringify(stats,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='office-politics-career.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(a==='home'){closeModal();window.scrollTo({top:0,behavior:'smooth'});return;}if(a==='resume')return connect(saved.token);
 if(a==='copy'){try{await navigator.clipboard.writeText(state.code);toast('Room code copied. Send it to your colleagues.');}catch{toast('Room code: '+state.code);}return;}
 if(a==='leave'){if(await act('leave')){stream?.close();state=null;token=null;saved=null;drawer=null;chatOpen=false;save('op-session',null);try{sessionStorage.removeItem('op-token');}catch{}closeModal();render();}return;}
 if(a==='mute'){if(muted.has(id))muted.delete(id);else muted.add(id);save('op-muted',[...muted]);render();return;}
 if(a==='task')return taskModal(id);if(a==='answer'){taskAnswer=[n];renderTask();return;}
 if(a==='move-up'||a==='move-down'){const j=n+(a==='move-up'?-1:1);[taskAnswer[n],taskAnswer[j]]=[taskAnswer[j],taskAnswer[n]];renderTask();return;}
 if(a==='submit-task'){if(!taskAnswer.length)return toast('Select an answer first.');b.disabled=true;if(await act('task',{id:modal.id,answer:taskAnswer})){closeModal();toast('Contribution filed. Check the project board for today’s rewards.');}else b.disabled=false;return;}
 if(a==='select-vote'){voteTarget=id;render();return;}if(a==='vote')return act('vote',{target:voteTarget==='abstain'?null:voteTarget});
 if(a==='chat')return act('chat',{text:state.catalog.prompts[n]});if(a==='appeal')return act('appeal',{text:explanations[n]});if(a==='accept'||a==='reject')return act('appealVote',{accept:a==='accept'});
 if(a==='sabotage'){if(state.catalog.actions[n]==='Gossip'){openModal('gossip',`<h2 id="modal-title">Start a little gossip.</h2><p>Choose who receives an unverified preset rumor. Your identity stays hidden.</p>${state.players.filter(p=>p.alive&&p.id!==state.me.id).map(p=>`<button class="button secondary appeal-option" data-action="gossip-target" data-id="${p.id}">${esc(p.name)}</button>`).join('')}`);return;}if(await act('sabotage',{action:state.catalog.actions[n]}))toast('Your action is complete. Keep up appearances.');return;}
 if(a==='gossip-target'){if(await act('sabotage',{action:'Gossip',target:id}))closeModal();return;}
 if(['ready','start','rematch','restore','influence','nextPhase','fillSeats'].includes(a))return act(a);
});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focus=[...document.querySelectorAll('.modal button:not(:disabled), .modal input, .modal select, .modal textarea, .modal [tabindex="0"]')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();if(token)connect(token);else if(new URLSearchParams(location.search).has('room'))entryModal(true);
